-- DISI rollback of Migration 057 (benchmark bWAR evidence).
-- database/release/sql/rollback-057.sql, generated by database/research/057/build.mjs from the same research files as the migration.
--
-- Use only if a production failure requires it. One transaction, guarded. It restores the pre-057 logical state: the 54 team-season rows 057
-- added are RETRACTED with a stated reason (the 032 guard forbids deleting a team-season fact; a retracted fact is sealed and is never read by a
-- label, a value view or a reconciliation), the eleven career bWAR values 057 set return to NULL, the six bWAR model-evaluation rows 057 stored
-- are removed (the reach evaluation was never touched), and the product snapshots are refreshed once. The two source rows stay as provenance.
-- 057 can be applied again afterwards: it inserts fresh ACTIVE rows beside the retracted ones.
--
-- Order: 057 is rolled back before any earlier benchmark rollback. rollback-050 refuses once any team-season row (ACTIVE or RETRACTED) exists
-- for a player it covers, so after 057 has been applied once rollback-050 is no longer available (it covers all eleven; the ledger
-- never deletes). rollback-055 and rollback-056 are unaffected: no 057 player belongs to their populations.

begin;

create temporary table _r057 on commit drop as
select $r057${"baseline":{"support":[{"labelled_n":11,"negative_n":10,"positive_n":1,"reference_population":"DODGERS_TRACKED_AND_OPENING_CLASS","support_state":"BASELINE_NOT_SUPPORTED","target_key":"BWAR_2_WITHIN_10_SEASONS"},{"labelled_n":75,"negative_n":72,"positive_n":3,"reference_population":"TOP_PROSPECT_SAMPLE","support_state":"BASELINE_NOT_SUPPORTED","target_key":"BWAR_2_WITHIN_10_SEASONS"},{"labelled_n":11,"negative_n":11,"positive_n":0,"reference_population":"DODGERS_TRACKED_AND_OPENING_CLASS","support_state":"BASELINE_NOT_SUPPORTED","target_key":"DODGERS_MLB_VALUE_WITHIN_10_SEASONS"},{"labelled_n":11,"negative_n":10,"positive_n":1,"reference_population":"DODGERS_TRACKED_AND_OPENING_CLASS","support_state":"BASELINE_NOT_SUPPORTED","target_key":"POSITIVE_BWAR_WITHIN_10_SEASONS"},{"labelled_n":75,"negative_n":68,"positive_n":7,"reference_population":"TOP_PROSPECT_SAMPLE","support_state":"BASELINE_NOT_SUPPORTED","target_key":"POSITIVE_BWAR_WITHIN_10_SEASONS"},{"labelled_n":25,"negative_n":23,"positive_n":2,"reference_population":"DODGERS_TRACKED_AND_OPENING_CLASS","support_state":"BASELINE_NOT_SUPPORTED","target_key":"REACH_MLB_WITHIN_7_SEASONS"},{"labelled_n":166,"negative_n":132,"positive_n":34,"reference_population":"TOP_PROSPECT_SAMPLE","support_state":"BASELINE_SUPPORTED","target_key":"REACH_MLB_WITHIN_7_SEASONS"}],"war_active":1880},"evaluation_fingerprints":["102c01a35d380d36493465cef1070c07","1aa73185a9dab3071d4530ee670dd088"],"players":[{"bref_id":"dejesen01","career_bwar":"-0.18","slug":"emmanuel-dejesus"},{"bref_id":"guerrvl02","career_bwar":"25.73","slug":"vladimir-guerrero-jr"},{"bref_id":"celesgi01","career_bwar":"0.24","slug":"gilberto-celestino"},{"bref_id":"pachecr01","career_bwar":"-1.30","slug":"cristian-pache"},{"bref_id":"gimenan01","career_bwar":"19.37","slug":"andres-gimenez"},{"bref_id":"taverle01","career_bwar":"4.70","slug":"leody-taveras"},{"bref_id":"sotoju01","career_bwar":"42.57","slug":"juan-soto"},{"bref_id":"amayami01","career_bwar":"3.35","slug":"miguel-amaya"},{"bref_id":"muzzisi01","career_bwar":"-0.05","slug":"simon-muzziotti"},{"bref_id":"tatisfe02","career_bwar":"27.34","slug":"fernando-tatis-jr"},{"bref_id":"marchra01","career_bwar":"1.41","slug":"rafael-marchan"}],"source_urls":["https://web.archive.org/web/20260911214553id_/https://www.baseball-reference.com/data/war_daily_bat.txt","https://web.archive.org/web/20260210222101id_/https://www.baseball-reference.com/data/war_daily_pitch.txt"]}$r057$::jsonb as j;

create temporary table _r057_players on commit drop as
select x ->> 'slug' as slug, x ->> 'bref_id' as bref_id, (x ->> 'career_bwar')::numeric as career_bwar from _r057, jsonb_array_elements(j -> 'players') x;

create temporary table _r057_sources on commit drop as
select so.id from public.sources so where so.url in (select jsonb_array_elements_text(j -> 'source_urls') from _r057);

create temporary table _r057_support on commit drop as
select x ->> 'target_key' as target_key, x ->> 'reference_population' as reference_population, (x ->> 'labelled_n')::int as labelled_n,
  (x ->> 'positive_n')::int as positive_n, (x ->> 'negative_n')::int as negative_n, x ->> 'support_state' as support_state
from _r057, jsonb_array_elements(j #> '{baseline,support}') x;

create temporary table _r057_before on commit drop as
select (select md5(string_agg(t, '|' order by t)) from (select m::text as t from public.outcome_model_evaluations m where m.target_key = 'REACH_MLB_WITHIN_7_SEASONS') x) as reach_evaluation_hash,
  (select md5(string_agg(t, '|' order by t)) from (select w::text as t from public.player_mlb_team_season_war w where w.source_id not in (select id from _r057_sources)) x) as other_war_hash;

-- ===========================================================================
-- 1. GUARDS
-- ===========================================================================

do $$
begin
  if not exists (select 1 from public.player_mlb_team_season_war w where w.source_id in (select id from _r057_sources) and w.record_status = 'ACTIVE') then
    raise exception 'rollback-057: Migration 057 is not applied';
  end if;
  -- later research must not depend on what is retracted
  if exists (select 1 from public.player_mlb_team_season_war w where w.supersedes_record_id in (select id from public.player_mlb_team_season_war where source_id in (select id from _r057_sources)))
     or exists (select 1 from public.player_mlb_team_season_war w where w.source_id in (select id from _r057_sources) and w.bref_id not in (select bref_id from _r057_players))
     or exists (select 1 from public.outcomes oc join public.players pl on pl.id = oc.player_id join _r057_players p on p.slug = pl.slug
                where oc.career_war is distinct from p.career_bwar)
     or exists (select 1 from public.outcome_model_evaluations m where m.target_key in ('POSITIVE_BWAR_WITHIN_10_SEASONS', 'BWAR_2_WITHIN_10_SEASONS')
                and m.training_fingerprint not in (select jsonb_array_elements_text(j -> 'evaluation_fingerprints') from _r057)) then
    raise exception 'rollback-057: later research depends on the 057 evidence (a superseding fact, another career bWAR or a later bWAR evaluation); rollback refused';
  end if;
end $$;

-- ===========================================================================
-- 2. RETRACT THE 057 TEAM-SEASON ROWS, RESTORE CAREER bWAR, REMOVE THE bWAR EVALUATIONS
-- ===========================================================================

update public.player_mlb_team_season_war w set record_status = 'RETRACTED', retracted_at = now(),
  retraction_reason = 'Rollback of Migration 057 (benchmark bWAR evidence): the archived-capture facts are withdrawn and the pre-057 state restored.'
where w.source_id in (select id from _r057_sources) and w.record_status = 'ACTIVE' and w.bref_id in (select bref_id from _r057_players);

update public.outcomes oc set career_war = null
from _r057_players p join public.players pl on pl.slug = p.slug
where oc.player_id = pl.id and oc.career_war = p.career_bwar;

delete from public.outcome_model_evaluations
where target_key in ('POSITIVE_BWAR_WITHIN_10_SEASONS', 'BWAR_2_WITHIN_10_SEASONS')
  and training_fingerprint in (select jsonb_array_elements_text(j -> 'evaluation_fingerprints') from _r057);

-- ===========================================================================
-- 3. POSTCONDITIONS AND ONE REFRESH
-- ===========================================================================

do $$
declare
  b record;
begin
  select * into b from _r057_before;
  if exists (select 1 from public.player_mlb_team_season_war w where w.source_id in (select id from _r057_sources) and w.record_status = 'ACTIVE')
     or (select count(*) from public.player_mlb_team_season_war where record_status = 'ACTIVE') <> (select (j #>> '{baseline,war_active}')::int from _r057)
     or b.other_war_hash is distinct from (select md5(string_agg(t, '|' order by t)) from (select w::text as t from public.player_mlb_team_season_war w
          where w.source_id not in (select id from _r057_sources)) x) then
    raise exception 'rollback-057 postcondition: the pre-057 active team-season rows are not restored exactly';
  end if;
  if exists (select 1 from public.outcomes oc join public.players pl on pl.id = oc.player_id join _r057_players p on p.slug = pl.slug where oc.career_war is not null) then
    raise exception 'rollback-057 postcondition: a career bWAR 057 set is still present';
  end if;
  if (select count(*) from public.outcome_model_evaluations) <> 3
     or exists (select 1 from public.outcome_model_evaluations where target_key <> 'REACH_MLB_WITHIN_7_SEASONS')
     or b.reach_evaluation_hash is distinct from (select md5(string_agg(t, '|' order by t)) from (select m::text as t from public.outcome_model_evaluations m where m.target_key = 'REACH_MLB_WITHIN_7_SEASONS') x)
     or exists (select 1 from public.v_outcome_model_evaluation where not evaluation_current) then
    raise exception 'rollback-057 postcondition: the stored evaluation is not the current reach evaluation alone';
  end if;
  if exists (select target_key, reference_population, labelled_n, positive_n, negative_n, support_state from public.v_outcome_target_support
             except select target_key, reference_population, labelled_n, positive_n, negative_n, support_state from _r057_support)
     or (select count(*) from public.v_outcome_target_support) <> (select count(*) from _r057_support) then
    raise exception 'rollback-057 postcondition: target support is not the pre-057 support';
  end if;
  if exists (select 1 from public.v_outcome_training_population t join _r057_players p on p.slug = t.player_slug
             where t.target_key in ('POSITIVE_BWAR_WITHIN_10_SEASONS', 'BWAR_2_WITHIN_10_SEASONS') and (t.label is not null or t.training_state <> 'OUTCOME_UNAUDITED')) then
    raise exception 'rollback-057 postcondition: a bWAR label of the eleven survived';
  end if;
end $$;

select * from public.disi_refresh_product_snapshots();

commit;
